export function sportBenefit(salary,fizoPercent,selection,{military=false}={}){const rates={'80':80,'90':90,'100-ms':100,'100-msmk':100,'100-zms':100};const rate=rates[selection]||0;const requiresMilitary=selection==='80'||selection==='90';const suitable=rate>0&&(!requiresMilitary||military);const applied=suitable;const percent=Math.max(fizoPercent,applied?rate:0);return {rate,suitable,requiresMilitary,applied,percent,amount:Math.round(salary*percent)/100,potential:Math.round(salary*rate)/100,source:applied&&rate>fizoPercent?'sport':'fizo'};}
